<?php session_start();if(empty($_SESSION['sa'])){header('Location: ../index.php');exit;}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><div class="app wide"><div class="brand">Traccar <span>Migration Tool</span></div><div class="steps"><b class="done">✓ Origen</b><i></i><b class="on">2 Usuarios</b><i></i><b>3 Destino</b><i></i><b>4 Migración</b></div><main class="card"><div class="head"><div><small>PASO 2</small><h1>Usuarios del origen</h1><p><?=htmlspecialchars($_SESSION['sa']['url'])?></p></div><button id="load">Cargar usuarios</button></div><div id="msg" class="msg"></div><div id="selectbar" class="selectbar hide"><label><input id="all" type="checkbox"> Seleccionar todos</label><span id="count">0 seleccionados</span></div><div id="table" class="table hide"></div><div class="actions"><a href="../index.php">← Volver</a><button id="next" class="disabled">Continuar →</button></div></main></div><script>
const load=document.getElementById('load'),all=document.getElementById('all'),table=document.getElementById('table'),bar=document.getElementById('selectbar'),count=document.getElementById('count'),next=document.getElementById('next');
load.onclick=async()=>{load.disabled=true;load.textContent='Cargando...';try{let r=await fetch('../api/importar_usuarios.php'),d=await r.json();if(!d.ok)throw Error(d.mensaje);table.innerHTML='<table><thead><tr><th>ID SA</th><th>Nombre</th><th>Email</th><th>Teléfono</th><th>Estado</th><th>Expiración</th><th>✓</th></tr></thead><tbody>'+d.usuarios.map(u=>'<tr><td>'+x(u.id)+'</td><td>'+x(u.name)+'</td><td>'+x(u.email)+'</td><td>'+x(u.phone||'—')+'</td><td>'+(u.disabled?'Deshabilitado':'Activo')+'</td><td>'+x(u.expirationTime||'—')+'</td><td><input class="u" type="checkbox" value="'+u.id+'"></td></tr>').join('')+'</tbody></table>';table.classList.remove('hide');bar.classList.remove('hide');document.querySelectorAll('.u').forEach(c=>c.onchange=update);update();}catch(e){document.getElementById('msg').textContent=e.message}finally{load.disabled=false;load.textContent='Cargar usuarios'}};
all.onchange=()=>{document.querySelectorAll('.u').forEach(c=>c.checked=all.checked);update()};function update(){let a=[...document.querySelectorAll('.u')],s=a.filter(c=>c.checked);count.textContent=s.length+' seleccionados';all.checked=a.length>0&&s.length==a.length;next.classList.toggle('disabled',!s.length)}next.onclick=async()=>{let ids=[...document.querySelectorAll('.u:checked')].map(c=>+c.value);if(!ids.length)return;let r=await fetch('../api/seleccionar_usuarios.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids})}),d=await r.json();if(d.ok)location='destino.php';else alert(d.mensaje)};function x(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
</script></body></html>